def attach_particle(word: str, particle: str) -> str:
    # Get the last character
    last_char = word[-1]

    # Check if it's a digit
    if last_char.isdigit():
        # For multi-digit numbers, we need to determine how the full number is pronounced
        # Extract the numeric value
        num_str = ""
        for i in range(len(word) - 1, -1, -1):
            if word[i].isdigit():
                num_str = word[i] + num_str
            else:
                break

        num = int(num_str)

        # Sino-Korean number pronunciation
        # Map each digit/place to its pronunciation and whether it ends in batchim
        # Batchim endings: True if ends in consonant, False if ends in vowel

        def get_pronunciation_batchim(n):
            """Determine if a number ends in batchim when pronounced in Sino-Korean"""
            if n == 0:
                return False  # 공 (no batchim)

            # Handle units: 1-9
            units = {
                1: True,   # 일 (ㄹ)
                2: False,  # 이
                3: True,   # 삼 (ㅁ)
                4: False,  # 사
                5: False,  # 오
                6: True,   # 육 (ㄱ)
                7: True,   # 칠 (ㄹ)
                8: True,   # 팔 (ㄹ)
                9: False,  # 구
            }

            if n < 10:
                return units.get(n, False)
            elif n < 100:
                # 십 (ㅅ batchim) or tens + units
                tens_digit = n // 10
                ones_digit = n % 10
                if ones_digit == 0:
                    return True  # 십, 이십, etc. (all end in ㅅ)
                else:
                    return units.get(ones_digit, False)
            elif n < 1000:
                # 백 (ㄱ batchim) or hundreds + rest
                hundreds_digit = n // 100
                remainder = n % 100
                if remainder == 0:
                    return True  # 백, 이백, etc. (all end in ㄱ)
                else:
                    return get_pronunciation_batchim(remainder)
            elif n < 10000:
                # 천 (ㄴ batchim) or thousands + rest
                thousands_digit = n // 1000
                remainder = n % 1000
                if remainder == 0:
                    return True  # 천, 이천, etc. (all end in ㄴ)
                else:
                    return get_pronunciation_batchim(remainder)
            else:
                # For larger numbers, apply similar logic
                return False  # Default

        has_batchim = get_pronunciation_batchim(num)

        # Special case for "으로/로": ㄹ batchim takes "로"
        if particle == "으로/로":
            # For digits, ㄹ batchim digits are: 1, 7, 8, 10, 11, 17, 18, etc.
            # More generally: numbers whose Sino-Korean ends in ㄹ
            def ends_in_rieul(n):
                units_with_rieul = {1, 7, 8}
                if n < 10:
                    return n in units_with_rieul
                elif n < 100:
                    ones = n % 10
                    return ones in units_with_rieul
                elif n < 1000:
                    remainder = n % 100
                    return ends_in_rieul(remainder)
                elif n < 10000:
                    remainder = n % 1000
                    return ends_in_rieul(remainder)
                return False

            if ends_in_rieul(num):
                return word + "로"
            else:
                return word + ("으로" if has_batchim else "로")

        return word + ("은/는".split('/')[0] if has_batchim else "은/는".split('/')[1]) if particle == "은/는" else word + (particle.split('/')[0] if has_batchim else particle.split('/')[1])

    else:
        # It's a Hangul syllable
        char_code = ord(last_char)

        if 0xAC00 <= char_code <= 0xD7A3:
            # Hangul syllable
            relative_code = char_code - 0xAC00
            batchim = relative_code % 28
            has_batchim = batchim != 0

            # Special case for "으로/로": if batchim is ㄹ (=8), use "로"
            if particle == "으로/로":
                if batchim == 8:  # ㄹ
                    return word + "로"
                else:
                    return word + ("으로" if has_batchim else "로")
        else:
            has_batchim = False

    # Split the particle and choose the right form
    forms = particle.split('/')
    consonant_form = forms[0]
    vowel_form = forms[1]

    return word + (consonant_form if has_batchim else vowel_form)

